#include &lt;iterator&gt;
#include &lt;iostream&gt;

const std::vector&lt;int&gt;::iterator 
search (std::vector&lt;int&gt; v, const int find) {
    auto beg = v.begin();
    const auto end = v.end();

    while (beg != end) {
        if (*beg == find) {
            return beg;
        }
        ++beg;
    }

    return beg; // This can only be reached if beg = v.end()?
}

int 
main () {
