    if ($this-&gt;logfile === null)
    {
      echo "[".date("H:i:s", time())."]: logfile is null&lt;BR /&gt;";
      return false;
    }

    if (!is_resource($this-&gt;logfile))
    {
      echo "[".date("H:i:s", time())."]: logfile is NOT a resource, can't write {$str}&lt;BR /&gt;";
      return false;
