} NodeT;

typedef struct list {
    int length;
    NodeT* first , *last;
} ListT;


void insertWord(NodeT* Node, char* word) {
    if(!Node) || (!word) return;

    if(Node.words.word == NULL)
        Node.words.word = word;

    DataT* current = Node.words.next;

    while(current)
    {
        current = current.next;
    }
    (*current.next) = word;
}

