Here are some codes :

@Override
public void onResume() {
    super.onResume();
    camera = getCamera("back");
    currentCamera = 1;
    startPreview();
}

@Override
public void onPause() {
    if (inPreview) {
        camera.stopPreview();
    }
    camera.release();
    camera = null;
    inPreview = false;

    super.onPause();
}

private Camera.Size getOptimalPreviewSize(List&lt;Camera.Size&gt; sizes, int width, int height)
{
    // Source: http://stackoverflow.com/questions/7942378/android-camera-will-not-work-startpreview-fails
    Camera.Size optimalSize = null;

    final double ASPECT_TOLERANCE = 0.1;
    double targetRatio = (double) height / width;

    // Try to find a size match which suits the whole screen minus the menu on the left.
    for (Camera.Size size : sizes){

        if (size.height != width) continue;
        double ratio = (double) size.width / size.height;
        if (ratio &lt;= targetRatio + ASPECT_TOLERANCE &amp;&amp; ratio &gt;= targetRatio - ASPECT_TOLERANCE){
            optimalSize = size;
        }
    }

    // If we cannot find the one that matches the aspect ratio, ignore the requirement.
    if (optimalSize == null) {
        // TODO : Backup in case we don't get a size.
    }

    return optimalSize;
}

private void initPreview(int width, int height) {
    if (camera != null &amp;&amp; cameraPreviewHolder.getSurface() != null) {
        try {
            camera.setPreviewDisplay(cameraPreviewHolder);
        } catch (Throwable t) {
        }

        if (!cameraConfigured) {
            Camera.Parameters parameters = camera.getParameters();

            if (camera.getParameters().getSupportedPreviewSizes() != null){
                Camera.Size previewSize = getOptimalPreviewSize(camera.getParameters().getSupportedPreviewSizes(), width, height);;
                parameters.setPreviewSize(previewSize.width, previewSize.height);
            }
            camera.setParameters(parameters);
            cameraConfigured = true;
        }
    }
}

@TargetApi(Build.VERSION_CODES.JELLY_BEAN_MR1)
private void startPreview() {
    if (cameraConfigured &amp;&amp; camera != null) {
        camera.startPreview();
        inPreview = true;
        camera.setDisplayOrientation(90);
        if (Build.VERSION.SDK_INT &gt;= Build.VERSION_CODES.ICE_CREAM_SANDWICH_MR1) {
            camera.enableShutterSound(false);
        }
    }
}


