&lt;a }'' &lt;!-- --&gt;
&lt;a ['' &lt;!-- --&gt;
&lt;a ]'' &lt;!-- --&gt;
&lt;a ='' &lt;!-- --&gt;
&lt;a ?'' &lt;!-- --&gt;
&lt;a +'' &lt;!-- --&gt;
&lt;a `'' &lt;!-- --&gt;
&lt;a |'' &lt;!-- --&gt;
&lt;a ^'' &lt;!-- --&gt;
&lt;a ~'' &lt;!-- --&gt;
