starter.config(function($stateProvider, $urlRouterProvider) {
  $stateProvider
    .state('tabs', {
      url: '/tab',
      abstract: true,
      templateUrl: 'templates/tabs.html'
    })

    .state('tabs.home', {
      url: '/home',
      views: {
        'home-tab' : {
          templateUrl: 'templates/home.html'
        }
      }
    })

    .state('tabs.list', {
      url: '/list',
      views: {
        'list-tab' : {
          templateUrl: 'templates/list.html',
          controller: 'ListController'
        }
      }
    })

    .state('tabs.detail', {
      url: '/list/:aId',
      views: {
        'list-tab' : {
          templateUrl: 'templates/detail.html',
          controller: 'ListController'
        }
      }
    });


  $urlRouterProvider.otherwise('/tab/home');
});

starter.controller('ListController', ['$scope', '$http', '$state',
    function($scope, $http, $state) {

    $scope.posts = [];  
    var startingPoint = 0;
    var limit = 1;

    $scope.load=function(startingPoint, limit){

    $http.get('js/data.json').success(function(data) {

      for(var i = startingPoint; i&lt;=limit; i+=1){
          $scope.posts.push(data.posts[i]);
          $scope.whichpost=$state.params.aId;
      }

    })
     .finally(function(){
                    $scope.$broadcast('scroll.refreshComplete');
                    $scope.$broadcast('scroll.infiniteScrollComplete');
                });

    };

    $scope.get_more = function(){
                $scope.load(startingPoint, limit);
                limit+=2;
                startingPoint+=2;
            };   

    $scope.noMore = function(){
        return ($scope.posts.length &gt; 50) ? false : true;
    };

}]);


