        public ObservableCollection&lt;String&gt; ComboBoxItems
        {
            get
            {
                if (items == null)
                {
                    items = new ObservableCollection&lt;string&gt;();
                    items.Add("A");
                    items.Add("B");
                    items.Add("C");
                    items.Add("D");
