Model/Profile.php:

&lt;?php


 namespace Admin\Model;

 use Zend\InputFilter\InputFilter;
 use Zend\InputFilter\InputFilterAwareInterface;
 use Zend\InputFilter\InputFilterInterface;

 class Profile implements InputFilterAwareInterface
 {
 public $id;
 public $name;
 public $email;
 public $password;

 protected $inputFilter;

 public function exchangeArray($data)
 {
     $this-&gt;id     = (!empty($data['id'])) ? $data['id'] : null;
     $this-&gt;name = (!empty($data['name'])) ? $data['name'] : null;
     $this-&gt;email  = (!empty($data['email'])) ? $data['email'] : null;
     $this-&gt;password  = (!empty($data['password'])) ? $data['password'] : null;     

 }


public function __set($name, $value) {
    $method = 'set' . $name;
    if (!method_exists($this, $method)) {
        throw new Exception('Invalid Method');
    }
    $this-&gt;$method($value); 
}

public function __get($name) {
    $method = 'get' . $name;
    if (!method_exists($this, $method)) {
        throw new Exception('Invalid Method');
    }
    return $this-&gt;$method();
}

 public function getArrayCopy()
 {
     return get_object_vars($this);
 }

 public function setInputFilter(InputFilterInterface $inputFilter)
 {
     throw new \Exception("Not used");
 }

 public function getInputFilter()
 {
     if (!$this-&gt;inputFilter) {
         $inputFilter = new InputFilter();

         $inputFilter-&gt;add(array(
             'name'     =&gt; 'id',
             'required' =&gt; true,
             'filters'  =&gt; array(
                 array('name' =&gt; 'Int'),
             ),
         ));

         $inputFilter-&gt;add(array(
             'name'     =&gt; 'name',
             'required' =&gt; true,
             'filters'  =&gt; array(
                 array('name' =&gt; 'StripTags'),
                 array('name' =&gt; 'StringTrim'),
             ),
             'validators' =&gt; array(
                 array(
                     'name'    =&gt; 'StringLength',
                     'options' =&gt; array(
                         'encoding' =&gt; 'UTF-8',
                         'min'      =&gt; 1,
                         'max'      =&gt; 100,
                     ),
                 ),
             ),
         ));

         $inputFilter-&gt;add(array(
             'name'     =&gt; 'email',
             'required' =&gt; true,
             'filters'  =&gt; array(
                 array('name' =&gt; 'StripTags'),
                 array('name' =&gt; 'StringTrim'),
             ),
             'validators' =&gt; array(
                 array(
                     'name'    =&gt; 'EmailAddress',
                     'options' =&gt; array(
                         'domain' =&gt; true, 
                     ),
                 ),

             ),
         ));


         $this-&gt;inputFilter = $inputFilter;
     }

     return $this-&gt;inputFilter;
 }


}


Model/ProfileTable.php:

&lt;?php

namespace Admin\Model;


 use Zend\Db\TableGateway\TableGateway;

 use Zend\Db\Adapter\Adapter;

 class ProfileTable
 {
     protected $tableGateway;  



 public function __construct(TableGateway $tableGateway)
 {
     $this-&gt;tableGateway = $tableGateway;

 } 

public function fetchAll($user_email)
{ 
    $resultSet = $this-&gt;tableGateway-&gt;select(array('email' =&gt;$user_email));
    return $resultSet;     
}

public function getProfile($id)
{
    $id  = (int) $id;
    $rowset = $this-&gt;tableGateway-&gt;select(array('id' =&gt; $id));
    $row = $rowset-&gt;current('id');  
    if (!$row) {
        throw new \Exception("Could not find row $id");             
    }

    return $row;
}


 public function saveProfile(Profile $profile)
 {
     $data = array(
         'name' =&gt; $profile-&gt;name,
         'email'  =&gt; $profile-&gt;email, 
     );

     $id = (int) $profile-&gt;id;
     if ($id == 0) {
         $this-&gt;tableGateway-&gt;insert($data);
     } else {
         if ($this-&gt;getProfile($id)) {
             $this-&gt;tableGateway-&gt;update($data, array('id' =&gt; $id));
         } else {
             throw new \Exception('Profile id does not exist');
         }
     }
 } 

 }


