    {
        Console.WriteLine("Number of FizzBuzz: ");
        return countOfFizzBuzz;
    }

    public int TotalPrime(int countOfPrime)
    {
        Console.WriteLine("Number of Prime: ");
        return countOfPrime;
    }

}

